<section class="container section"><p class="eyebrow">ADMINISTRACIÓN</p><h1><?= e($title) ?></h1><div class="editor-layout"><div class="form-panel"><h2><?= $id ? 'Editar registro #' . e($id) : 'Crear registro' ?></h2><?php require ROOT . '/app/Views/errors.php'; ?><form method="post" action="<?= e(url('admin/contenido', ['mod' => $module, 'id' => $id])) ?>" data-submit data-confirm="¿Guardar estos cambios? Si publicas, activas o marcas como vigente, el contenido podrá verse en el portal."><?= csrf() ?>
<?php foreach ($fields as $key => [$label, $type, $rule]): ?><label for="<?= e($key) ?>"><?= e($label) ?></label>
<?php if (in_array($type, ['select', 'category'], true)): ?><select name="<?= e($key) ?>" id="<?= e($key) ?>" required><option value="">Selecciona una opción</option><?php foreach ($rule as $value => $text): ?><option value="<?= e($value) ?>" <?= (string)($values[$key] ?? '') === (string)$value ? 'selected' : '' ?>><?= e($text) ?></option><?php endforeach; ?></select>
<?php elseif ($type === 'textarea'): ?><textarea id="<?= e($key) ?>" name="<?= e($key) ?>" rows="6" maxlength="<?= e($rule) ?>" required><?= e($values[$key] ?? '') ?></textarea>
<?php else: ?><input type="<?= e($type) ?>" id="<?= e($key) ?>" name="<?= e($key) ?>" maxlength="<?= e($rule) ?>" value="<?= e($values[$key] ?? '') ?>" required><?php endif; ?><?php endforeach; ?><p class="muted">Guardar aplica el estado seleccionado. El texto se muestra sin interpretar HTML.</p><div class="actions"><button class="button" type="submit">Guardar cambios</button><?php if ($id): ?><a href="<?= e(url('admin/contenido', ['mod' => $module])) ?>">Cancelar edición</a><?php endif; ?></div></form></div>
<div><h2>Registros guardados</h2><?php if (!$rows): ?><p class="empty">Todavía no hay registros. Crea el primero con el formulario.</p><?php else: ?><div class="table-wrap" tabindex="0" role="region" aria-label="Registros guardados"><table><thead><tr><th>ID</th><th>Registro</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= e($row['id']) ?></td><td><?= e($row['titulo'] ?? $row['nombre'] ?? (($fields['categoria_id'][2][$row['categoria_id']] ?? '') . ' · ' . \App\Services\Catalog::days()[$row['dia']] . ' ' . substr($row['hora_inicio'], 0, 5))) ?></td><td><span class="badge"><?= e($row['estado'] ?? (isset($row['activo']) ? ($row['activo'] ? 'Activa' : 'Inactiva') : ($row['vigente'] ? 'Vigente' : 'No vigente'))) ?></span></td><td><a href="<?= e(url('admin/contenido', ['mod' => $module, 'id' => $row['id']])) ?>" aria-label="Editar registro <?= e($row['id']) ?>">Editar</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><div class="actions pager"><?php if ($page > 1): ?><a href="<?= e(url('admin/contenido', ['mod' => $module, 'page' => $page - 1])) ?>">Anterior</a><?php endif; ?><?php if ($more): ?><a href="<?= e(url('admin/contenido', ['mod' => $module, 'page' => $page + 1])) ?>">Siguiente</a><?php endif; ?></div></div></div></section>
